from itertools import product

alph = sorted('ЛУНАТИК')

ans = []
for pos, val in enumerate(product(alph, repeat=6), start=1):
    val = ''.join(val)
    if val[0] == 'Н':
        if sum(1 for i in val if i in 'АИУ') == 1:
            ans.append(pos)

print(max(ans))

from itertools import product

res = 0
for idx, word in enumerate(product(sorted('ПОБЕДА'), repeat=6), start=1):
    if word[0] == "О" and not (idx % 2) and len(set(word)) == 6:
        res = idx

print(res)
